# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRET YOLCULUĞU: SEVR MAĞARASI VE YOLDAKİ HADİSELER</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Sevr Mağarası (3 Gün)</text>\n  <text x="38" y="100" font-size="11" fill="#334155">• Medine kuzeyde iken tedbir</text>\n  <text x="46" y="116" font-size="11" fill="#334155">için güneydeki Sevr\'e gidildi.</text>\n  <text x="38" y="138" font-size="11" font-weight="bold" fill="#1e40af">• &quot;Üzülme! Allah bizimledir.&quot;</text>\n  <text x="46" y="154" font-size="10.5" fill="#475569">(Tevbe suresi, 40. ayet)</text>\n  <text x="38" y="176" font-size="11" fill="#334155">• Güvercin yuvası ve örümcek</text>\n  <text x="46" y="192" font-size="11" fill="#334155">ağıyla ilahi yardım gerçekleşti.</text>\n  <text x="127" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Rehber: Abdullah bin Uraykıt</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">2. Sürâka bin Mâlik Olayı</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Müşriklerin koyduğu 100 deve</text>\n  <text x="268" y="116" font-size="11" fill="#334155">ödül için peşlerine düştü.</text>\n  <text x="260" y="138" font-size="11" fill="#334155">• Yaklaştığında atının ayakları</text>\n  <text x="268" y="154" font-size="11" fill="#334155">defalarca kuma saplandı.</text>\n  <text x="260" y="176" font-size="11" fill="#334155">• Pişman olup eman diledi;</text>\n  <text x="268" y="192" font-size="11" fill="#334155">takipçileri geri çevirdi.</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Kisrâ\'nın bilezikleri müjdesi!</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="572" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Ümmü Ma\'bed Çadırı</text>\n  <text x="483" y="100" font-size="11" fill="#334155">• Kudeyd mevkiinde cömert bir</text>\n  <text x="491" y="116" font-size="11" fill="#334155">hanım olan Ümmü Ma\'bed\'in</text>\n  <text x="491" y="132" font-size="11" fill="#334155">çadırına uğradılar.</text>\n  <text x="483" y="154" font-size="11" fill="#334155">• Kuraklıktan sütü kesilmiş</text>\n  <text x="491" y="170" font-size="11" fill="#334155">zayıf keçiyi Bismillah ile</text>\n  <text x="491" y="186" font-size="11" fill="#334155">sıvazlayınca bol süt verdi.</text>\n  <text x="572" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Bereket mucizesi ve Hilye tarifi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUBÂ MESCİDİ, İLK CUMA NAMAZI VE MEDİNE\'YE VARIŞ (622)</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kubâ Mescidi ve İlk Cuma Namazı</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Kubâ\'ya Varış:</tspan> Mekke\'den çıkan Hz. Ali\'yi</text>\n  <text x="58" y="120" font-size="11" fill="#475569">beklerken Külsûm bin Hidm\'in evinde misafir</text>\n  <text x="58" y="136" font-size="11" fill="#475569">oldu; İslam\'ın ilk mescidi <tspan font-weight="bold">Kubâ Mescidi</tspan> yapıldı.</text>\n  <text x="48" y="164" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Ranuna Vadisi:</tspan> Cuma günü Medine\'ye</text>\n  <text x="58" y="182" font-size="11" fill="#475569">hareket edildi; Sâlim b. Avf yurdundaki Ranuna</text>\n  <text x="58" y="198" font-size="11" fill="#475569">Vadisi\'nde <tspan font-weight="bold">ilk Cuma hutbesi ve namazı</tspan> kılındı.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Medine\'de Coşkulu Karşılama ve Kusvâ</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• Medineli Müslümanlar (<tspan font-weight="bold">Ensar</tspan>) kasidelerle</text>\n  <text x="388" y="120" font-size="11" fill="#475569">(Tale\'al-bedru aleynâ) Peygamberimizi karşıladı.</text>\n  <text x="378" y="146" font-size="11.5" fill="#334155">• Kimseyi kırmamak için devesi <tspan font-weight="bold" fill="#92400e">Kusvâ</tspan>\'yı</text>\n  <text x="388" y="164" font-size="11" fill="#475569">serbest bıraktı; Kusvâ boş bir arsaya çöktü.</text>\n  <text x="378" y="190" font-size="11.5" fill="#334155">• Mescid-i Nebevî inşa edilene kadar</text>\n  <text x="388" y="208" font-size="11.5" font-weight="bold" fill="#b45309">Ebû Eyyûb el-Ensârî (Halid b. Zeyd)</text>\n  <text x="388" y="224" font-size="11" fill="#334155">evinde 7 ay misafir olarak kaldı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRET\'İN İSLAM TARİHİNDEKİ SONUÇLARI VE TEMEL KAVRAMLAR</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hicret\'in Tarihi Sonuçları</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• Müslümanlar baskı ve işkenceden kurtulup</text>\n  <text x="58" y="120" font-size="11" fill="#475569">inançlarını özgürce yaşama imkânı buldu.</text>\n  <text x="48" y="144" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Yesrib</tspan> şehrinin adı <tspan font-weight="bold" fill="#166534">Medînetü\'n-Nebî</tspan></text>\n  <text x="58" y="162" font-size="11" fill="#475569">(Peygamber Şehri / Medine) olarak değişti.</text>\n  <text x="48" y="186" font-size="11.5" fill="#334155">• İslam devletinin temelleri atıldı; Hz. Ömer</text>\n  <text x="58" y="204" font-size="11" fill="#475569">döneminde <tspan font-weight="bold">Hicrî Takvim</tspan> başlangıcı kabul edildi.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Hicret Kavramları</text>\n  <text x="378" y="104" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Muhacir:</tspan> İnançları uğruna Mekke\'deki ev ve</text>\n  <text x="388" y="122" font-size="11" fill="#475569">mallarını bırakıp Medine\'ye göç eden Müslümanlar.</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Ensar:</tspan> Muhacirlere kucak açıp her türlü</text>\n  <text x="388" y="166" font-size="11" fill="#475569">yardımı yapan Medineli Müslümanlar (Yardımcılar).</text>\n  <text x="378" y="192" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Muâhât:</tspan> Ensar ile Muhacir arasında kurulan</text>\n  <text x="388" y="210" font-size="11" fill="#475569">eşsiz İslam kardeşliği (Mekke-Medine kenetlenmesi).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
